def has_no_more_than_three_digits(file_name):
    return sum(c.isdigit() for c in file_name) <= 3

def has_exactly_one_dot(file_name):
    return file_name.count('.') == 1

def has_valid_prefix(file_name):
    parts = file_name.split('.')
    if len(parts) != 2:
        return False
    prefix = parts[0]
    return prefix and prefix[0].isalpha()

def has_valid_extension(file_name):
    parts = file_name.split('.')
    if len(parts) != 2:
        return False
    extension = parts[1]
    return extension in ['txt', 'exe', 'dll']

